SELECT p.gender, p.anchor_age, p.anchor_year, p.anchor_year_group, i.discharge_location, COUNT(i.subject_id) AS n, AVG(i.los) AS average_los, MEDIAN(i.los) AS median_los, SUM(CASE WHEN i.discharge_location IN ('home', 'hospice') AND i.los <= 10 THEN 1 ELSE 0 END)::FLOAT / NULLIF(COUNT(i.subject_id), 0) AS proportion_short_los FROM patients p JOIN icustays i ON p.subject_id = i.subject_id WHERE p.gender = 'F' AND p.anchor_age BETWEEN 63 AND 73 AND p.anchor_year_group = 'ICU stay' GROUP BY p.gender, p.anchor_age, p.anchor_year, p.anchor_year_group, i.discharge_location;